// Auto-generated seed data for Vercel Serverless environment
import zlib from "node:zlib";

const GZIPPED_DATA = "";

export interface SeedPayload {
  chunks: Array<{
    id: string;
    file_path: string;
    file_name: string;
    doc_id: string;
    department: string;
    category: string;
    date: string;
    source: string;
    content: string;
    token_count?: number;
    checksum?: string;
    enriched_content?: string;
    doc_title?: string;
  }>;
  faqs: Array<{
    id: number;
    question: string;
    answer: string;
    active: number;
  }>;
}

let cachedSeed: SeedPayload | null = null;

export function getSeedData(): SeedPayload {
  if (!cachedSeed) {
    const buf = Buffer.from(GZIPPED_DATA, "base64");
    const json = zlib.gunzipSync(buf).toString("utf-8");
    cachedSeed = JSON.parse(json);
  }
  return cachedSeed!;
}
